/**
 * Practice Questions Database for All Exams
 * Questions organized by topic with explanations
 */

export interface PracticeQuestion {
  id: string;
  question: string;
  options?: string[];
  correctAnswer?: number; // Index of correct option
  explanation: string;
  difficulty: 'Easy' | 'Medium' | 'Hard';
  topic: string;
  isEssay?: boolean;
  rubric?: string; // Grading rubric for essay questions
  /** Reading passage this question depends on, resolved from the group's first question. */
  passage?: string;
}

export interface TopicQuestions {
  topicId: string;
  topicName: string;
  questions: PracticeQuestion[];
}

