// Helper function to get questions for an exam
export function getQuestionsByExamId(examId: string): Record<string, TopicQuestions> {
  const questionsMap: Record<string, Record<string, TopicQuestions>> = {
    sat: SAT_QUESTIONS,
    act: ACT_QUESTIONS,
    gre: GRE_QUESTIONS,
    gmat: GMAT_QUESTIONS,
    shsat: SHSAT_QUESTIONS,
    regents: REGENTS_QUESTIONS,
  };

  return questionsMap[examId] || SAT_QUESTIONS;
}

const FOLLOW_UP_MARKER = /^\s*\(Same (?:passage|argument) as above\.?\)\s*/i;
const PASSAGE_LABEL = /^\s*\*{0,2}(?:Passage|Argument):\*{0,2}\s*/i;
/** Below this length a question cannot realistically contain an embedded reading passage. */
const MIN_EMBEDDED_PASSAGE_LENGTH = 350;
/** Quote-led passages (SHSAT/ACT style) can be shorter, but still need real substance. */
const MIN_QUOTED_PASSAGE_LENGTH = 150;

function isFollowUp(text: string): boolean {
  return FOLLOW_UP_MARKER.test(text);
}

/** True when the question embeds its own passage instead of referring back to an earlier one. */
export function questionCarriesPassage(text: string): boolean {
  if (isFollowUp(text)) return false;
  if (PASSAGE_LABEL.test(text)) return true;
  if (/^\s*"/.test(text) && text.length >= MIN_QUOTED_PASSAGE_LENGTH) return true;
  return text.length >= MIN_EMBEDDED_PASSAGE_LENGTH;
}

/**
 * Pull just the passage out of a question that embeds one, dropping the prompt that trails it.
 * Falls back to the whole text when the prompt cannot be identified confidently.
 */
function extractPassage(text: string): string {
  const body = text.replace(PASSAGE_LABEL, '');
  const lastQuote = body.lastIndexOf('"');
  if (lastQuote > 0) {
    const trailing = body.slice(lastQuote + 1);
    // Only strip the tail when it looks like a short prompt rather than more passage text.
    if (trailing.length < 200 && /[?:]/.test(trailing)) {
      return body.slice(0, lastQuote + 1).trim();
    }
  }
  return body.trim();
}

/**
 * Reading topics store the passage on the first question of each group; the following questions
 * refer back to it. Carry that passage forward so every question can stand on its own.
 *
 * Two authoring formats exist: follow-ups tagged "(Same passage as above.)" (ACT/GRE/GMAT/SHSAT),
 * and untagged follow-ups after a "Passage:"-labelled question (Regents). Untagged attachment is
 * limited to explicitly labelled groups so a merely long question never seeds a bogus passage.
 */
function attachPassages(questions: PracticeQuestion[]): PracticeQuestion[] {
  const hasTaggedFollowUps = questions.some((q) => isFollowUp(q.question));
  const hasLabelledPassages = questions.some(
    (q) => !isFollowUp(q.question) && PASSAGE_LABEL.test(q.question)
  );
  if (!hasTaggedFollowUps && !hasLabelledPassages) return questions;

  let current: string | undefined;
  return questions.map((q) => {
    if (questionCarriesPassage(q.question)) {
      current = extractPassage(q.question);
      return q;
    }
    if (!current || q.isEssay) return q;

    if (isFollowUp(q.question)) {
      return { ...q, question: q.question.replace(FOLLOW_UP_MARKER, ''), passage: current };
    }
    if (hasLabelledPassages && !hasTaggedFollowUps) {
      return { ...q, passage: current };
    }
    return q;
  });
}

// Get questions for a specific topic
export function getQuestionsByTopic(examId: string, topicId: string): PracticeQuestion[] {
  const questions = getQuestionsByExamId(examId);
  return attachPassages(questions[topicId]?.questions || []);
}

// Get a single question by ID
export function getQuestionById(examId: string, topicId: string, questionId: string): PracticeQuestion | null {
  const questions = getQuestionsByTopic(examId, topicId);
  return questions.find((q) => q.id === questionId) || null;
}

// Total number of practice questions available for an exam
export function countQuestionsByExamId(examId: string): number {
  return Object.values(getQuestionsByExamId(examId)).reduce(
    (sum, topic) => sum + topic.questions.length,
    0
  );
}
